   199→        }
   200→        public bool AddToBalanceAndCreateIfNotExists(Address address, in UInt256 balanceChange, IReleaseSpec spec)
   201→        {
   202→            DebugGuardInScope();
   203→            return _stateProvider.AddToBalanceAndCreateIfNotExists(address, balanceChange, spec);
   204→        }
   205→        public void SubtractFromBalance(Address address, in UInt256 balanceChange, IReleaseSpec spec)
