    76→        public void Restore(int snapshot)
    77→        {
    78→            if (_logger.IsTrace) _logger.Trace($"Restoring storage snapshot {snapshot}");
    79→
    80→            int currentPosition = _changes.Count - 1;
    81→            if (snapshot > currentPosition)
    82→            {
    83→                throw new InvalidOperationException($"{GetType().Name} tried to restore snapshot {snapshot} beyond current position {currentPosition}");
    84→            }
    85→
    86→            if (snapshot == currentPosition)
    87→            {
    88→                return;
    89→            }
    90→
    91→            for (int i = 0; i < currentPosition - snapshot; i++)
    92→            {
    93→                Change change = _changes[currentPosition - i];
    94→                StackList<int> stack = _intraBlockCache[change!.StorageCell];
    95→                if (stack.Count == 1)
    96→                {
    97→                    if (_changes[stack.Peek()]!.ChangeType == ChangeType.JustCache)
    98→                    {
    99→                        int actualPosition = stack.Pop();
   100→                        if (actualPosition != currentPosition - i)
   101→                        {
   102→                            throw new InvalidOperationException($"Expected actual position {actualPosition} to be equal to {currentPosition} - {i}");
   103→                        }
   104→
   105→                        _keptInCache.Add(change);
   106→                        _changes[actualPosition] = default;
   107→                        continue;
   108→                    }
   109→                }
   110→
   111→                int forAssertion = stack.Pop();
   112→                if (forAssertion != currentPosition - i)
   113→                {
   114→                    throw new InvalidOperationException($"Expected checked value {forAssertion} to be equal to {currentPosition} - {i}");
   115→                }
   116→
   117→                _changes[currentPosition - i] = default;
   118→
   119→                if (stack.Count == 0)
   120→                {
   121→                    _intraBlockCache.Remove(change.StorageCell);
   122→                }
   123→            }
   124→
   125→            CollectionsMarshal.SetCount(_changes, snapshot + 1);
   126→            currentPosition = _changes.Count - 1;
   127→            foreach (Change kept in _keptInCache)
   128→            {
   129→                currentPosition++;
   130→                _changes.Add(kept);
   131→                _intraBlockCache[kept.StorageCell].Push(currentPosition);
   132→            }
   133→
   134→            _keptInCache.Clear();
   135→
   136→            while (_transactionChangesSnapshots.TryPeek(out int lastOriginalSnapshot) && lastOriginalSnapshot > snapshot)
   137→            {
   138→                _transactionChangesSnapshots.Pop();
   139→            }
   140→
   141→        }
