   282→        /// <param name="address">Contract address</param>
   283→        public virtual void ClearStorage(Address address)
   284→        {
   285→            // We are setting cached values to zero so we do not use previously set values
   286→            // when the contract is revived with CREATE2 inside the same block
   287→            foreach (KeyValuePair<StorageCell, StackList<int>> cellByAddress in _intraBlockCache)
   288→            {
