   298→        /// </summary>
   299→        protected readonly struct Change(in StorageCell storageCell, byte[] value, ChangeType changeType)
   300→        {
   301→            public readonly StorageCell StorageCell = storageCell;
   302→            public readonly byte[] Value = value;
   303→            public readonly ChangeType ChangeType = changeType;
   304→
   305→            public bool IsNull => ChangeType == ChangeType.Null;
   306→        }
