    84→        public PatriciaTree(ITrieStore trieStore, ILogManager logManager, ICappedArrayPool? bufferPool = null)
    85→            : this(trieStore.GetTrieStore(null), EmptyTreeHash, true, logManager, bufferPool: bufferPool)
    86→        {
    87→        }
    88→
    89→        public PatriciaTree(IScopedTrieStore trieStore, ILogManager logManager, ICappedArrayPool? bufferPool = null)
    90→            : this(trieStore, EmptyTreeHash, true, logManager, bufferPool: bufferPool)
    91→        {
    92→        }
    93→
    94→        public PatriciaTree(
    95→            IKeyValueStoreWithBatching keyValueStore,
    96→            Hash256 rootHash,
    97→            bool allowCommits,
    98→            ILogManager logManager,
    99→            ICappedArrayPool? bufferPool = null)
   100→            : this(
   101→                new RawScopedTrieStore(new NodeStorage(keyValueStore), null),
   102→                rootHash,
   103→                allowCommits,
   104→                logManager,
   105→                bufferPool: bufferPool)
   106→        {
   107→        }
   108→
   109→        public PatriciaTree(
   110→            IScopedTrieStore? trieStore,
   111→            Hash256 rootHash,
   112→            bool allowCommits,
   113→            ILogManager? logManager,
   114→            ICappedArrayPool? bufferPool = null)
   115→        {
   116→            _logger = logManager?.GetClassLogger<PatriciaTree>() ?? throw new ArgumentNullException(nameof(logManager));
   117→            TrieStore = trieStore ?? throw new ArgumentNullException(nameof(trieStore));
   118→            _allowCommits = allowCommits;
   119→            RootHash = rootHash;
   120→
   121→            // TODO: cannot do that without knowing whether the owning account is persisted or not
   122→            // RootRef?.MarkPersistedRecursively(_logger);
   123→
   124→            _bufferPool = bufferPool;
   125→        }
   126→
   127→        public void Commit(bool skipRoot = false, WriteFlags writeFlags = WriteFlags.None)
   128→        {
   129→            if (!_allowCommits)
   130→            {
   131→                ThrowReadOnlyTrieException();
   132→            }
   133→
