public ref ChangeTrace GetValueRefOrAddDefault(UInt256 storageCellIndex, out bool exists)
{
    ref ChangeTrace value = ref CollectionsMarshal.GetValueRefOrAddDefault(_dictionary, storageCellIndex, out exists);
